if(!obterTokenCliente())location.href='login.html';(async()=>{try{const ps=await apiFetch('/pedidos/meus');const elegiveis=ps.filter(p=>p.estado==='entregue');const el=document.getElementById('devolucao-pedido');el.innerHTML=elegiveis.length?elegiveis.map(p=>`<option value="${p.numeroPedido}">#${p.numeroPedido}</option>`).join(''):'<option value="">Não existem encomendas elegíveis.</option>';}catch(e){document.getElementById('devolucao-pedido').replaceChildren(new Option(e.message||'Não foi possível carregar pedidos.',''))}})();document.getElementById('form-devolucao').addEventListener('submit',async e=>{e.preventDefault();const m=document.getElementById('devolucao-msg'),b=e.currentTarget.querySelector('button');m.textContent='A enviar...';b.disabled=true;try{await apiFetch('/publico/devolucoes',{method:'POST',body:JSON.stringify({numeroPedido:document.getElementById('devolucao-pedido').value,motivo:document.getElementById('devolucao-motivo').value,detalhes:document.getElementById('devolucao-detalhes').value})});m.textContent='Pedido enviado para análise.';e.currentTarget.reset()}catch(err){m.textContent=err.message}finally{b.disabled=false}});
